{% include "afmco/templates/print/fonts.html" %}
{% set company = frappe.db.get_single_value("Global Defaults", "default_company") or "" %}
{% set logo = "/files/Logo-01.png" %}
{% set _co_logo = (frappe.db.get_value("Company", company, "company_logo") if company else None) or "/files/Logo-01.png" %}
{% set logo_url = frappe.utils.get_url(_co_logo) %}
{% set date_fmt = doc.required_arrival_date and frappe.utils.formatdate(doc.required_arrival_date, "dd/MM/yyyy") or "" %}
{% set time_fmt = doc.required_arrival_time and frappe.utils.format_time(doc.required_arrival_time, "HH:mm") or "" %}
{% set emp_list = (doc.employees or []) %}
{% set unreg_list = (doc.unregistered_employee or []) %}
{% set total = (emp_list|length) + (unreg_list|length) %}
{% set amount_str = frappe.utils.fmt_money(doc.amount or 0, currency="SAR") %}

<style type="text/css">
  * { margin:0; padding:0; box-sizing:border-box; }
  body { font-family: Tajawal, Montserrat, sans-serif; font-size:11px; color:#171717; }
  .sheet, .sheet td, .sheet div, .sheet span, .sheet th { font-family: Tajawal, Montserrat, sans-serif; }
  table { border-collapse:collapse; width:100%; }
  .sheet td { vertical-align:top; padding:10mm; width:50%; }

  .ticket { border:1px dashed #5f5f5f; padding:6mm; page-break-inside:avoid; background:#fff; }
  .header { background:#00844e; color:#fff; -webkit-print-color-adjust:exact; print-color-adjust:exact; text-align:center; padding:6px; }
  .logo {
      display:block; 
      margin:0 auto; 
      height:auto; 
      width:30mm; 
      background:#fff; 
      padding:0px; 

  }
  .title { font-size:13px; font-weight:bold; letter-spacing:0.3px; margin-top:4px; color:#fff; }
  .doc-info { font-size:10px; opacity:0.9; margin-top:2px; color:#fff; font-family: Tajawal, Montserrat, sans-serif; }

  .section { margin:6px 0 8px 0; border-top:1px solid #d0d0d0; padding-top:6px; }
  .section-title { color:#00844e; font-weight:bold; font-size:11px; margin-bottom:4px; text-transform:uppercase; }

  .row { margin:2px 0; }
  .label { display:inline-block; width:42%; font-size:9px; color:#5f5f5f; }
  .value { display:inline-block; width:56%; font-size:10px; font-weight:bold; color:#171717; }
  .highlight { background:#f4f4f4; -webkit-print-color-adjust:exact; print-color-adjust:exact; padding:1px 3px; }

  .table { width:100%; border-collapse:collapse; margin-top:4px; }
  .table thead tr { background:#00844e !important; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .table thead th { background:#00844e !important; -webkit-print-color-adjust:exact; print-color-adjust:exact; color:#fff; font-size:9px; text-align:left; padding:3px; font-weight:normal; }
  .table tbody td { font-size:9px; padding:3px; border-bottom:1px solid #d0d0d0; color:#171717; }
  .table tbody td:first-child, .table tbody td:last-child { direction:ltr; unicode-bidi:embed; text-align:right; font-family: Tajawal, Montserrat, sans-serif; }

  .qr { text-align:center; margin:6px 0; }
  .qr img {
    width:120px;
    height:120px;
    display:inline-block;
    border:1px solid #d0d0d0;
    padding:2px;
    background:#fff;
  }

  .footer { text-align:center; font-size:8px; color:#5f5f5f; margin-top:6px; border-top:1px solid #d0d0d0; padding-top:5px; }
  .guides { margin-top:6px; text-align:center; font-size:9px; color:#5f5f5f; }
  .guides span { border-top:1px dashed #5f5f5f; display:block; margin:6px 0 0 0; padding-top:4px; }
</style>

<table class="sheet">
  <tr>
    <!-- 1) REQUEST (Top Left) -->
    <td>
      <div class="ticket">
        <div class="header">

          <div class="title">TRANSFER REQUEST</div>
          <div class="doc-info">{{ doc.name }}</div>
        </div>

        <div class="section">
          <div class="section-title">Trip Details</div>
          <div class="row"><span class="label">Type:</span><span class="value">{{ doc.trip_type or "-" }}</span></div>
          <div class="row"><span class="label">Date:</span><span class="value highlight">{{ date_fmt }}</span></div>
          <div class="row"><span class="label">Time:</span><span class="value highlight">{{ time_fmt }}</span></div>
          {% if doc.trip_type == "Out City" %}
          <div class="row"><span class="label">From:</span><span class="value">{{ doc.current_city or "-" }}</span></div>
          <div class="row"><span class="label">To:</span><span class="value">{{ doc.destination_city or "-" }}</span></div>
          {% endif %}
        </div>

        <div class="section">
          <div class="section-title">Transport</div>
          <div class="row"><span class="label">Method:</span><span class="value">{{ doc.transport_type or "-" }}</span></div>
          {% if doc.transport_type == "Supplier" %}
          <div class="row"><span class="label">Supplier:</span><span class="value">{{ doc.supplier_name or "-" }}</span></div>
          <div class="row"><span class="label">Mobile:</span><span class="value">{{ doc.supplier_mobile or "-" }}</span></div>
          <div class="row"><span class="label">Amount:</span><span class="value highlight">{{ amount_str }}</span></div>
          {% elif doc.transport_type == "From Company" %}
          <div class="row"><span class="label">Driver:</span><span class="value">{{ doc.driver or "-" }}</span></div>
          {% endif %}
        </div>

        <div class="section">
          <div class="section-title">All Passengers ({{ total }})</div>
          <table class="table">
            <thead>
              <tr>
                <th style="width:10%">#</th>
                <th style="width:50%">Name</th>
                <th style="width:40%">Mobile</th>
              </tr>
            </thead>
            <tbody>
              {% set counter = 0 %}
              {% for r in emp_list %}
              {% set counter = counter + 1 %}
              <tr>
                <td>{{ counter }}</td>
                <td>{{ r.name1 or r.employee or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
              {% for r in unreg_list %}
              {% set counter = counter + 1 %}
              <tr>
                <td>{{ counter }}</td>
                <td>{{ r.name1 or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
            </tbody>
          </table>
        </div>

        <div class="footer">REQUEST COPY — {{ company }}</div>
                   {% if logo_url %}<img src="{{ logo_url }}" class="logo">{% endif %}
        <div class="guides"><span>Cut here</span></div>
      </div>
    </td>

    <!-- 2) SUPPLIER/DRIVER (Top Right) -->
    <td>
      <div class="ticket">
        <div class="header">
          <div class="title">{% if doc.transport_type == "Supplier" %}SUPPLIER ORDER{% else %}DRIVER ORDER{% endif %}</div>
          <div class="doc-info">{{ doc.name }}</div>
        </div>

        <div class="section">
          <div class="section-title">Trip Information</div>
          <div class="row"><span class="label">Date:</span><span class="value highlight">{{ date_fmt }}</span></div>
          <div class="row"><span class="label">Time:</span><span class="value highlight">{{ time_fmt }}</span></div>
          <div class="row"><span class="label">Passengers:</span><span class="value highlight">{{ total }}</span></div>
          {% if doc.transport_type == "Supplier" %}
          <div class="row"><span class="label">Amount:</span><span class="value highlight">{{ amount_str }}</span></div>
          {% endif %}
        </div>

        {% if doc.pickup_location %}
        <div class="section">
          <div class="section-title">Pickup Location</div>
          <div class="qr">
            <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&format=png&data={{ doc.pickup_location|urlencode }}" alt="QR">
          </div>
        </div>
        {% endif %}

        {% if doc.dropoff_location %}
        <div class="section">
          <div class="section-title">Dropoff Location</div>
          <div class="qr">
            <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&format=png&data={{ doc.dropoff_location|urlencode }}" alt="QR">
          </div>
        </div>
        {% endif %}

        <div class="section">
          <div class="section-title">Contact</div>
          <div class="row"><span class="label">Supervisor:</span><span class="value">{{ doc.current_housing_supervisor_mobile or "-" }}</span></div>
        </div>

        <div class="footer">{% if doc.transport_type == "Supplier" %}SUPPLIER COPY{% else %}DRIVER COPY{% endif %}</div>
                   {% if logo_url %}<img src="{{ logo_url }}" class="logo">{% endif %}
        <div class="guides"><span>Cut here</span></div>
      </div>
    </td>
  </tr>

  <tr>
    <!-- 3) BOARDING PASS (Bottom Left) -->
    <td>
      <div class="ticket">
        <div class="header">
          <div class="title">BOARDING PASS</div>
          <div class="doc-info">{{ doc.name }}</div>
        </div>

        <div class="section">
          <div class="section-title">Trip Schedule</div>
          <div class="row"><span class="label">Date:</span><span class="value highlight">{{ date_fmt }}</span></div>
          <div class="row"><span class="label">Time:</span><span class="value highlight">{{ time_fmt }}</span></div>
          {% if doc.trip_type == "Out City" %}
          <div class="row"><span class="label">Route:</span><span class="value">{{ doc.current_city or "-" }} → {{ doc.destination_city or "-" }}</span></div>
          {% endif %}
        </div>

        <div class="section">
          <div class="section-title">Pickup Point</div>
          {% if doc.pickup_location %}
          <div class="qr">
            <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&format=png&data={{ doc.pickup_location|urlencode }}" alt="QR">
          </div>
          {% else %}
          <div style="text-align:center; padding:6px;">Location to be confirmed</div>
          {% endif %}
        </div>

        <div class="section">
          <div class="section-title">All Passengers</div>
          <table class="table">
            <thead>
              <tr>
                <th style="width:10%">#</th>
                <th style="width:50%">Name</th>
                <th style="width:40%">Mobile</th>
              </tr>
            </thead>
            <tbody>
              {% set counter = 0 %}
              {% for r in emp_list %}
              {% set counter = counter + 1 %}
              <tr>
                <td>{{ counter }}</td>
                <td>{{ r.name1 or r.employee or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
              {% for r in unreg_list %}
              {% set counter = counter + 1 %}
              <tr>
                <td>{{ counter }}</td>
                <td>{{ r.name1 or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
            </tbody>
          </table>
        </div>

        <div class="footer">BOARDING PASS — Keep this for boarding</div>
                   {% if logo_url %}<img src="{{ logo_url }}" class="logo">{% endif %}
        <div class="guides"><span>Cut here</span></div>
      </div>
    </td>

    <!-- 4) OPERATIONS (Bottom Right) -->
    <td>
      <div class="ticket">
        <div class="header">
          <div class="title">OPERATIONS COPY</div>
          <div class="doc-info">{{ doc.name }}</div>
        </div>

        <div class="section">
          <div class="section-title">Request Summary</div>
          <div class="row"><span class="label">Method:</span><span class="value">{{ doc.transport_type or "-" }}</span></div>
          <div class="row"><span class="label">Status:</span><span class="value highlight">{{ doc.workflow_state or "Draft" }}</span></div>
          <div class="row"><span class="label">Payment:</span><span class="value">{{ doc.payment_order_status or "Not Created" }}</span></div>
        </div>

        <div class="section">
          <div class="section-title">Schedule</div>
          <div class="row"><span class="label">Date:</span><span class="value">{{ date_fmt }}</span></div>
          <div class="row"><span class="label">Time:</span><span class="value">{{ time_fmt }}</span></div>
          <div class="row"><span class="label">Total PAX:</span><span class="value highlight">{{ total }}</span></div>
        </div>

        {% if doc.transport_type == "Supplier" %}
        <div class="section">
          <div class="section-title">Supplier</div>
          <div class="row"><span class="label">Name:</span><span class="value">{{ doc.supplier_name or "-" }}</span></div>
          <div class="row"><span class="label">Mobile:</span><span class="value">{{ doc.supplier_mobile or "-" }}</span></div>
          <div class="row"><span class="label">Amount:</span><span class="value highlight">{{ amount_str }}</span></div>
        </div>
        {% elif doc.transport_type == "From Company" %}
        <div class="section">
          <div class="section-title">Fleet</div>
          <div class="row"><span class="label">Driver:</span><span class="value">{{ doc.driver or "-" }}</span></div>
          <div class="row"><span class="label">Vehicle:</span><span class="value">Company Fleet</span></div>
        </div>
        {% endif %}

        <div class="section">
          <div class="section-title">Complete Passenger List</div>
          <table class="table">
            <thead>
              <tr>
                <th style="width:10%">#</th>
                <th style="width:50%">Name</th>
                <th style="width:40%">Mobile</th>
              </tr>
            </thead>
            <tbody>
              {% set n = 0 %}
              {% for r in emp_list %}
              {% set n = n + 1 %}
              <tr>
                <td>{{ n }}</td>
                <td>{{ r.name1 or r.employee or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
              {% for r in unreg_list %}
              {% set n = n + 1 %}
              <tr>
                <td>{{ n }}</td>
                <td>{{ r.name1 or "-" }}</td>
                <td>{{ r.cell_number or "-" }}</td>
              </tr>
              {% endfor %}
            </tbody>
          </table>
        </div>

        <div class="footer">OPERATIONS — {{ company }}</div>
                   {% if logo_url %}<img src="{{ logo_url }}" class="logo">{% endif %}
        <div class="guides"><span>Cut here</span></div>
      </div>
    </td>
  </tr>
</table>
